<?php
if (PHP_SAPI!=='cli') exit;
require SIS_ROOT.'/app/lib/bulk-accounts.php';
$bulk=new BulkAccounts($c,$power); $bulk->install();
Auth::actAs((int)$c->legacyId($power,'SIS'));
$bt1=GS::saveTeacher(null,'BULK001','Juan Dela Cruz');
$bt2=GS::saveTeacher(null,'BULK002','Juan Dela Cruz');
$bs1=GS::saveStudent(null,['studentId'=>'BULKST001','studentName'=>'Bulk Student One','sectionId'=>$section]);
$bs2=GS::saveStudent(null,['studentId'=>'BULKST002','studentName'=>'Bulk Student Two','sectionId'=>$section]);
$preview=$bulk->preview('TEACHER',[$bt1,$bt2,$teacher]);
ca_test('bulk preview is read-only, skips linked records and allocates distinct surname usernames',function()use($preview,$c,$bt1){ca_ok($preview[0]['username']==='jdelacruz');ca_ok($preview[1]['username']==='jdelacruz2');ca_ok($preview[2]['status']==='Skipped');ca_ok(!$c->one('SELECT account_id FROM central_person_links WHERE teacher_doc_id=?',[$bt1]));});
$created=[];
ca_test('bulk teacher accounts share a password with different hashes and verified identity links',function()use($bulk,$preview,$c,&$created){foreach(array_slice($preview,0,2) as $r)$created[]=$bulk->create('TEACHER',$r,'SharedTemporary123',7);ca_ok($created[0]['status']==='Created'&&$created[1]['status']==='Created');$hashes=[];foreach($created as $r){ca_ok($c->verifyPassword($r['account_id'],'SharedTemporary123'));ca_ok($c->group($r['account_id'])==='TEACHER');ca_ok($c->account($r['account_id'])['teacher_doc_id']===$r['record_id']);ca_ok((bool)$c->account($r['account_id'])['must_change_password']);$hashes[]=Db::val('SELECT password_hash FROM central_credentials WHERE account_id=?',[$r['account_id']]);}ca_ok($hashes[0]!==$hashes[1]);});
ca_test('bulk retries never reset an existing or disabled account',function()use($bulk,$preview,$created,$c){$id=$created[0]['account_id'];$c->q("UPDATE central_accounts SET status='DISABLED' WHERE id=?",[$id]);$hash=Db::val('SELECT password_hash FROM central_credentials WHERE account_id=?',[$id]);$r=$bulk->create('TEACHER',$preview[0],'OtherTemporary123',7);ca_ok($r['status']==='Skipped');ca_ok(Db::val('SELECT password_hash FROM central_credentials WHERE account_id=?',[$id])===$hash);ca_ok($c->account($id)['status']==='DISABLED');});
ca_test('bulk student IDs become usernames and account ownership is exact',function()use($bulk,$bs1,$c){$r=$bulk->preview('STUDENT',[$bs1])[0];ca_ok($r['username']==='bulkst001');$r=$bulk->create('STUDENT',$r,'SharedTemporary123',7);ca_ok($r['status']==='Created');ca_ok($c->group($r['account_id'])==='STUDENT');ca_ok($c->account($r['account_id'])['student_doc_id']===$bs1);ca_ok($c->permissions($r['account_id'])['portal.grades.view']==='OWN');ca_ok(!$c->can($r['account_id'],'grading.workspace.view'));});
ca_test('bulk preview flags legacy users, missing records and username conflicts',function()use($bulk,$bs2,$c,$power){$c->save($power,['group'=>'STUDENT','username'=>'bulkst002','full_name'=>'Unrelated Applicant','status'=>'ACTIVE','temp_password'=>'OtherTemporary123']);ca_ok($bulk->preview('STUDENT',[$bs2])[0]['status']==='Needs review');ca_ok($bulk->preview('TEACHER',['missing'])[0]['status']==='Missing information');ca_ok($bulk->preview('TEACHER',['legacy-missing'])[0]['status']!=='Ready');});
ca_test('bulk temporary password expiry blocks login and active sessions, SIS reset recovers',function()use($c,$created,$power){$id=$created[1]['account_id'];$c->login('jdelacruz2','SharedTemporary123','SIS');$c->q('UPDATE central_temporary_password_expiry SET expires_at=NOW()-INTERVAL 1 DAY WHERE account_id=?',[$id]);ca_ok($c->current()===null);ca_denied(fn()=>$c->login('jdelacruz2','SharedTemporary123','GRADING'));$c->setPassword($id,'ResetTemporary123',true,$power);ca_ok(!$c->temporaryExpired($id));ca_ok($c->login('jdelacruz2','ResetTemporary123','SIS')['id']==$id);$c->changePassword($id,'ResetTemporary123','PersonalPassword123');ca_ok(!$c->account($id)['must_change_password']);ca_ok(!$c->verifyPassword($id,'SharedTemporary123'));});
ca_test('bulk administration rejects other groups, invalid passwords, and elevated account types',function()use($c,$teacherAccount,$bulk,$preview){ca_denied(fn()=>new BulkAccounts($c,$teacherAccount));ca_denied(fn()=>$bulk->preview('POWER_USER',['any']));ca_denied(fn()=>$bulk->create('TEACHER',$preview[0],'weak',7));ca_denied(fn()=>$bulk->create('TEACHER',$preview[0],'Temporary12345',90));});
ca_test('bulk audit never contains shared passwords',function(){ca_ok(!str_contains((string)Db::val("SELECT GROUP_CONCAT(details) FROM central_account_audit WHERE action='bulk_account_created'"),'SharedTemporary123'));});
